-- Unified, durable notification inbox for the Dori site.
-- Notifications are generated by trusted database triggers from committed activity.
create table if not exists public.dori_notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  category text not null check (category in ('bank','stock','attendance','achievement','mission','system')),
  title text not null check (length(btrim(title)) between 1 and 140),
  body text not null default '' check (length(body) <= 600),
  target_url text not null default './index.html' check (target_url !~* '^https?://'),
  metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object'),
  dedupe_key text,
  created_at timestamptz not null default clock_timestamp(),
  read_at timestamptz,
  constraint dori_notifications_user_dedupe_unique unique (user_id, dedupe_key)
);
create index if not exists dori_notifications_user_created_idx
  on public.dori_notifications(user_id, created_at desc);
create index if not exists dori_notifications_user_unread_idx
  on public.dori_notifications(user_id, created_at desc) where read_at is null;

alter table public.dori_notifications enable row level security;
drop policy if exists "Users can read their own notifications" on public.dori_notifications;
create policy "Users can read their own notifications" on public.dori_notifications
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Users can mark their own notifications read" on public.dori_notifications;
create policy "Users can mark their own notifications read" on public.dori_notifications
  for update to authenticated using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
revoke all on public.dori_notifications from public, anon, authenticated;
grant select on public.dori_notifications to authenticated;
grant update (read_at) on public.dori_notifications to authenticated;

create or replace function public.dori_notifications_mark_all_read()
returns integer language plpgsql security definer set search_path = ''
as $function$
declare v_uid uuid := auth.uid(); v_count integer := 0;
begin
  if v_uid is null then raise exception '로그인이 필요합니다.' using errcode = '28000'; end if;
  update public.dori_notifications set read_at = clock_timestamp()
  where user_id = v_uid and read_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;
create or replace function public.dori_notifications_delete_read()
returns integer language plpgsql security definer set search_path = ''
as $function$
declare v_uid uuid := auth.uid(); v_count integer := 0;
begin
  if v_uid is null then raise exception '로그인이 필요합니다.' using errcode = '28000'; end if;
  delete from public.dori_notifications where user_id = v_uid and read_at is not null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;
revoke all on function public.dori_notifications_mark_all_read() from public, anon;
grant execute on function public.dori_notifications_mark_all_read() to authenticated;
revoke all on function public.dori_notifications_delete_read() from public, anon;
grant execute on function public.dori_notifications_delete_read() to authenticated;

-- Notifications are based only on committed bank ledger rows.
create or replace function public.dori_notify_bank_transaction()
returns trigger language plpgsql security definer set search_path = ''
as $function$
declare v_uid uuid; v_title text; v_body text; v_target text;
begin
  if new.tx_type not in ('transfer_in','transfer_out') then return new; end if;
  select auth_user_id into v_uid from public.dori_bank_accounts
  where account_number = new.account_number and status = 'active' limit 1;
  if v_uid is null then return new; end if;
  if new.tx_type = 'transfer_in' or new.direction = 'credit' then
    v_title := '송금 도착';
    v_body := coalesce(nullif(btrim(new.counterparty_name),''),'다른 사용자') || '님이 '
      || to_char(new.amount,'FM999,999,999,999,999,999') || ' 돌돌코인을 보냈어요.';
  else
    v_title := '송금 완료';
    v_body := coalesce(nullif(btrim(new.counterparty_name),''),'다른 사용자') || '님에게 '
      || to_char(new.amount,'FM999,999,999,999,999,999') || ' 돌돌코인을 보냈어요.';
  end if;
  v_target := './dori-bank.html?transaction=' || new.transaction_ref::text || '#transactions';
  insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
  values (v_uid,'bank',v_title,v_body,v_target,
    jsonb_build_object('transaction_ref',new.transaction_ref,'transfer_ref',new.transfer_ref,'amount',new.amount),
    'bank-transaction:' || new.transaction_ref::text)
  on conflict (user_id,dedupe_key) do nothing;
  return new;
end;
$function$;
revoke all on function public.dori_notify_bank_transaction() from public, anon, authenticated;
drop trigger if exists dori_notification_bank_transaction on public.dori_bank_transactions;
create trigger dori_notification_bank_transaction after insert on public.dori_bank_transactions
for each row execute function public.dori_notify_bank_transaction();

-- Each successful stock execution notifies buyer and seller.
create or replace function public.dori_notify_stock_execution()
returns trigger language plpgsql security definer set search_path = ''
as $function$
declare v_stock_name text; v_value bigint; v_body text;
begin
  select name into v_stock_name from public.dori_stocks where id = new.stock_id;
  v_stock_name := coalesce(nullif(btrim(v_stock_name),''),'주식');
  v_value := coalesce(new.notional,new.quantity * new.price);
  v_body := v_stock_name || ' ' || to_char(new.quantity,'FM999,999,999,999') ||
    '주 · 체결가 ' || to_char(new.price,'FM999,999,999,999,999,999') ||
    ' D · 거래 금액 ' || to_char(v_value,'FM999,999,999,999,999,999') || ' D';
  if new.buyer_user_id is not null then
    insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
    values (new.buyer_user_id,'stock','주식 매수 체결',v_body,'./doldolstock.html',
      jsonb_build_object('execution_id',new.id,'stock_id',new.stock_id,'side','buy',
        'quantity',new.quantity,'price',new.price,'notional',v_value),
      'stock-execution:' || new.id::text || ':buyer')
    on conflict (user_id,dedupe_key) do nothing;
  end if;
  if new.seller_user_id is not null then
    insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
    values (new.seller_user_id,'stock','주식 매도 체결',v_body,'./doldolstock.html',
      jsonb_build_object('execution_id',new.id,'stock_id',new.stock_id,'side','sell',
        'quantity',new.quantity,'price',new.price,'notional',v_value),
      'stock-execution:' || new.id::text || ':seller')
    on conflict (user_id,dedupe_key) do nothing;
  end if;
  return new;
end;
$function$;
revoke all on function public.dori_notify_stock_execution() from public, anon, authenticated;
drop trigger if exists dori_notification_stock_execution on public.dori_stock_executions;
create trigger dori_notification_stock_execution after insert on public.dori_stock_executions
for each row execute function public.dori_notify_stock_execution();

-- Attendance messages are emitted only for server-verified attendance rows.
create or replace function public.dori_notify_attendance_day()
returns trigger language plpgsql security definer set search_path = ''
as $function$
declare v_uid uuid;
begin
  if new.user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return new; end if;
  v_uid := new.user_id::uuid;
  insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
  values (v_uid,'attendance','출석 체크 완료',
    to_char(new.reward_coins,'FM999,999,999,999,999,999') || ' 돌돌코인을 획득했어요. 내일도 출석해 보세요!',
    './index.html?open=attendance',
    jsonb_build_object('attendance_date',new.attendance_date,'reward_coins',new.reward_coins),
    'attendance:' || new.attendance_date::text)
  on conflict (user_id,dedupe_key) do nothing;
  return new;
end;
$function$;
revoke all on function public.dori_notify_attendance_day() from public, anon, authenticated;
drop trigger if exists dori_notification_attendance_day on public.user_attendance_days;
create trigger dori_notification_attendance_day after insert on public.user_attendance_days
for each row execute function public.dori_notify_attendance_day();

-- Mission notifications are generated on the actual completion transition.
create or replace function public.dori_notify_daily_mission()
returns trigger language plpgsql security definer set search_path = ''
as $function$
declare v_newly_completed boolean := false;
begin
  if tg_op = 'INSERT' then v_newly_completed := new.completed_at is not null;
  else v_newly_completed := old.completed_at is null and new.completed_at is not null;
  end if;
  if not v_newly_completed then return new; end if;
  insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
  values (new.user_id,'mission','일일 미션 완료',
    '미션 ' || new.mission_key || '을(를) 완료했어요. 오늘의 미션 진행도를 확인해 보세요.',
    './daily-missions.html',jsonb_build_object('mission_key',new.mission_key,'mission_date',new.mission_date),
    'mission:' || new.mission_date::text || ':' || new.mission_key)
  on conflict (user_id,dedupe_key) do nothing;
  return new;
end;
$function$;
revoke all on function public.dori_notify_daily_mission() from public, anon, authenticated;
drop trigger if exists dori_notification_daily_mission on public.user_daily_missions;
create trigger dori_notification_daily_mission after insert or update of completed_at on public.user_daily_missions
for each row execute function public.dori_notify_daily_mission();

-- Detect new keys added by the trusted achievement-claim RPC.
create or replace function public.dori_notify_new_achievements()
returns trigger language plpgsql security definer set search_path = ''
as $function$
declare v_pair record; v_value jsonb; v_name text; v_desc text; v_rarity text;
begin
  if jsonb_typeof(new.user_achievement) <> 'object' then return new; end if;
  if jsonb_typeof(old.user_achievement) = 'object' and new.user_achievement = old.user_achievement then return new; end if;
  for v_pair in select key,value from jsonb_each(new.user_achievement) loop
    if jsonb_typeof(coalesce(old.user_achievement,'{}'::jsonb)) <> 'object'
       or not (coalesce(old.user_achievement,'{}'::jsonb) ? v_pair.key) then
      v_value := v_pair.value;
      v_name := coalesce(nullif(v_value->>'이름',''),v_pair.key);
      v_desc := coalesce(nullif(v_value->>'설명',''),'새로운 업적을 달성했어요.');
      v_rarity := coalesce(v_value->>'희귀도','common');
      insert into public.dori_notifications(user_id,category,title,body,target_url,metadata,dedupe_key)
      values (new.user_id::uuid,'achievement','🏆 업적 달성 · ' || left(v_name,105),left(v_desc,600),
        './index.html?open=achievements',
        jsonb_build_object('achievement_id',v_pair.key,'rarity',v_rarity,'icon',v_value->>'아이콘','name',v_name),
        'achievement:' || v_pair.key)
      on conflict (user_id,dedupe_key) do nothing;
    end if;
  end loop;
  return new;
end;
$function$;
revoke all on function public.dori_notify_new_achievements() from public, anon, authenticated;
drop trigger if exists dori_notification_new_achievements on public.users;
create trigger dori_notification_new_achievements after update of user_achievement on public.users
for each row when (old.user_achievement is distinct from new.user_achievement)
execute function public.dori_notify_new_achievements();
